bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
const env=process.env;
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,
 password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try {
 const q=await pool.query('SELECT next_offset,last_complete_at IS NOT NULL AS full_pass FROM videobot_stars_refund_audit_cursor WHERE cursor_id=1');
 if(q.rows.length!==1)throw Error('CURSOR_NOT_FOUND');
 if(q.rows[0].full_pass!==true)process.exitCode=72;
 console.log(q.rows[0].full_pass?'STARS_OFFICIAL_AUDIT_FULL_PAGE_TRAVERSAL=PASS':'STARS_OFFICIAL_AUDIT_FULL_PAGE_TRAVERSAL=PARTIAL');
}catch(e){console.log('STARS_OFFICIAL_AUDIT_FULL_PAGE_TRAVERSAL=UNVERIFIED');process.exitCode=73;}
finally{await pool.end();}
NODE
